     * Returns a test for this filter.
     *
     * <p>The name is split on whitespace into terms, and every term must appear,
     * ignoring case and accents, in the first name or the last name.
     */
    public Predicate<Customer> asPredicate() {
        List<String> terms = terms(name);
        return customer -> {
            if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
                return false;
            }
            String firstName = fold(customer.firstName());
            String lastName = fold(customer.lastName());
            return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
        };
    }

    private static List<String> terms(String text) {
        return Arrays.stream(fold(text).split("[\\s\\p{Z}]+"))
                .filter(term -> !term.isEmpty())
                .toList();
    }

    /** Lower-cases text and strips accents, so that {@code Mäkinen} folds to {@code makinen}. */
    private static String fold(String text) {
        return Normalizer.normalize(text, Normalizer.Form.NFD)
                .replaceAll("\\p{M}+", "")
                .toLowerCase(Locale.ROOT);
    }
